use vstd::prelude::*;

verus! {

    // Construct a length‐n sequence over {'a','b'} (no 'c') such that
    // for every i with 0 ≤ i ≤ n−3, s[i] ≠ s[i+2].
    fn solve(n: i8) -> (res: Vec<char>)
        requires
            // problem assumes n ≥ 1
            n >= 1,
        ensures
            // length exactly n
            res.len() == (n as usize),
            // distance‐2 characters differ
            forall|i: usize| i + 2 < res.len() ==> res[i] != res[i+2],
            // only 'a' or 'b' appear
            forall|i: usize| i < res.len() ==> res[i] == 'a' || res[i] == 'b',
    {
        let mut res = Vec::<char>::new();
        let mut i: i8 = 0;
        while i < n
            invariant
                // loop index matches the vector length
                res.len() == (i as usize),
                // so far the distance‐2 constraint holds
                forall|j: usize| j + 2 < res.len() ==> res[j] != res[j+2],
                // and only 'a'/'b' have been used
                forall|j: usize| j < res.len() ==> res[j] == 'a' || res[j] == 'b',
            decreases
                // i increases toward n
                (n - i) as nat,
        {
            // pattern "a a b b" repeated ensures s[i] ≠ s[i+2]
            let c = if ((i as usize) % 4) < 2 { 'a' } else { 'b' };
            res.push(c);
            // we only need to check the new pair where j+2 = new_len−1,
            // i.e., j = new_len−3
            if res.len() >= 3 {
                let j = res.len() - 3;
                assert(res[j] != res[j + 2]);
            }
            i = i + 1;
        }
        res
    }

}

fn main() {
    // Example usage
    let v = solve(10);
    // v might be ["a","a","b","b","a","a","b","b","a","a"]
    assert(v.len() == 10);
}